-- Adds 16 market pages to an existing database: ten Atlantic Canada towns
-- (listed beside Truro) and six mid-size Canadian cities (beside Windsor).
-- The same content is in src/data/markets.json for fresh databases and the
-- build fallback. Markets that already exist are left exactly as they are.

insert into public.markets
  (slug, city, region, country, blurb, kicker, h1, lede, seo_title, seo_desc, stats, whats, seasons, faqs, sort_order)
values
  ($q$new-glasgow$q$, $q$New Glasgow$q$, $q$Nova Scotia$q$, $q$Canada$q$, $q$Pictou County's retail hub — a tight, loyal market where reputation travels faster than any ad.$q$, $q$Market page$q$, $q$Car dealership marketing in New Glasgow.$q$,
   $q$New Glasgow is where Pictou County shops. Stellarton, Westville, Trenton and Pictou all feed the same few kilometres of road, and in a community this close-knit, what people say about your store at the rink matters as much as anything you post.$q$,
   $q$Dealership Marketing in New Glasgow, Nova Scotia | Shawn Ryder Digital$q$, $q$Local SEO, Google Business Profile and review work for New Glasgow and Pictou County dealerships — built for a close-knit market where reputation decides the sale.$q$,
   $q$[{"k": "Town population", "v": "~9,500", "n": "The retail centre for a much larger county"}, {"k": "Pictou County", "v": "~44,000", "n": "The real catchment, all within a short drive"}, {"k": "Highway", "v": "104", "n": "Connects Truro, Antigonish and Cape Breton traffic"}, {"k": "Drive to Halifax", "v": "~1h 45m", "n": "Far enough that most buyers stay local"}]$q$::jsonb,
   $q$[{"h": "Everybody knows somebody who bought from you", "p": "Pictou County is small enough that one bad experience gets retold for years — and one great one does too. Reviews and how you reply to them carry more weight here than in any city market."}, {"h": "The 104 brings Cape Breton and the Strait through", "p": "Shoppers from Antigonish, Guysborough and Cape Breton pass through on their way to Truro and Halifax. Inventory pages and Google posts written for that drive-through buyer catch deals other stores never see."}, {"h": "Work vehicles and long commutes", "p": "Plenty of buyers commute to industrial and trades jobs across the county and beyond. Reliability, AWD, fuel cost and service turnaround matter more than trim levels."}, {"h": "Service is the relationship", "p": "With a limited number of stores, the service department is where loyalty is won or lost. A simple service-to-sales handoff is usually the cheapest deal available in the county."}]$q$::jsonb,
   $q$[{"when": "Oct–Nov", "h": "Winter tire rush", "p": "Tire storage and swap bookings fill fast. Open booking early and post when the weather turns."}, {"when": "Dec–Mar", "h": "Storms and the 104", "p": "Highway closures change shopping for days at a time. AWD, remote start and undercoating content earns attention."}, {"when": "Apr–Jun", "h": "Tax refund and spring trades", "p": "Spring is when trades come in. Merchandise used inventory well and make the trade-in process easy online."}, {"when": "Jul–Sep", "h": "Summer traffic and the ferry", "p": "Summer brings visitor traffic to Pictou and the PEI ferry. Out-of-town service work picks up — make sure your hours and phone numbers are right on Google."}]$q$::jsonb,
   $q$[{"q": "Can a Pictou County store compete with Truro and Halifax dealers online?", "a": "Yes, for local searches. Google weighs distance heavily, so a well-run profile with steady reviews wins most \"near me\" searches in the county. Where you lose is when your profile is half-finished."}, {"q": "What's the first thing to fix?", "a": "Usually the Google Business Profile — categories, departments, hours and photos — plus a real review ask at delivery and after service."}, {"q": "Is social worth it in a small market?", "a": "Yes, because people here know your staff. Real photos of real deliveries and team members outperform any manufacturer creative."}, {"q": "Should we advertise in Antigonish and Cape Breton?", "a": "Carefully. Target the people already willing to drive — specific models, price and availability — rather than trying to win their local searches."}]$q$::jsonb,
   coalesce((select sort_order from public.markets where slug = 'truro'), 0)),
  ($q$antigonish$q$, $q$Antigonish$q$, $q$Nova Scotia$q$, $q$Canada$q$, $q$A university town and the gateway to Cape Breton — with a trading area far bigger than its size.$q$, $q$Market page$q$, $q$Car dealership marketing in Antigonish.$q$,
   $q$Antigonish looks small on a map, but it's the shopping centre for the county, Guysborough and much of the Strait area. Add a university's worth of students and parents every fall, and you've got a market that rewards stores who know exactly who they're talking to.$q$,
   $q$Dealership Marketing in Antigonish, Nova Scotia | Shawn Ryder Digital$q$, $q$Dealership marketing for Antigonish: local SEO, Google profile and review work built for the county, the Strait area and the StFX community.$q$,
   $q$[{"k": "Town population", "v": "~4,700", "n": "The hub for a far bigger area"}, {"k": "Antigonish County", "v": "~20,000", "n": "Plus Guysborough and the Strait area"}, {"k": "University", "v": "StFX", "n": "Thousands of students and visiting families each year"}, {"k": "Highway", "v": "104", "n": "On the main route to Cape Breton"}]$q$::jsonb,
   $q$[{"h": "A regional hub, not a small town", "p": "Buyers drive in from Guysborough County, Port Hawkesbury and the rural county. Content and ads should speak to that whole radius, not just the town limits."}, {"h": "The StFX calendar matters", "p": "September and May bring students and parents shopping for reliable, affordable vehicles. A short, honest page on first cars and financing for students and new grads earns trust."}, {"h": "Cape Breton traffic passes the door", "p": "The 104 carries Cape Breton shoppers heading to the mainland. A well-kept Google profile and specific inventory posts catch people already on the road."}, {"h": "Word of mouth is the whole game", "p": "In a town this size, reviews and community involvement do more than any campaign. Sponsor something real and show it."}]$q$::jsonb,
   $q$[{"when": "Sep", "h": "Back to school", "p": "Students and parents shop for safe, affordable vehicles. Post your best value units and make financing questions easy to ask."}, {"when": "Oct–Dec", "h": "Winter prep", "p": "Winter tire and maintenance season. Keep online booking easy and your hours accurate on Google."}, {"when": "Jan–Apr", "h": "Storms and quiet months", "p": "Slower foot traffic — the best time to work your database with service-to-sales and equity offers."}, {"when": "May–Aug", "h": "Graduation and summer", "p": "Graduates buy their first new vehicle; summer brings visitor service work. Highland Games weekend traffic is real."}]$q$::jsonb,
   $q$[{"q": "Is there enough search volume in Antigonish to bother with SEO?", "a": "Volume is modest, but competition is lower still. Being the clear, well-reviewed answer for your area's searches is achievable and pays off."}, {"q": "Should we market to StFX students?", "a": "Yes, honestly. Clear information on financing, insurance basics and reliable used options builds goodwill with students and their parents."}, {"q": "Can we win shoppers from Port Hawkesbury and Guysborough?", "a": "Often, if you're the closest store with what they want. Inventory posts and Google profile work help them find you before they drive past."}, {"q": "What's the quickest win?", "a": "A complete Google profile with recent photos and a steady review ask. In a smaller market, that moves faster than anywhere else."}]$q$::jsonb,
   coalesce((select sort_order from public.markets where slug = 'truro'), 0)),
  ($q$bridgewater$q$, $q$Bridgewater$q$, $q$Nova Scotia$q$, $q$Canada$q$, $q$The South Shore's shopping centre — serving Lunenburg County and Queens with Halifax an hour away.$q$, $q$Market page$q$, $q$Car dealership marketing in Bridgewater.$q$,
   $q$Bridgewater is where the South Shore buys cars. Lunenburg, Mahone Bay, Chester and Liverpool shoppers all come here first — unless the Halifax stores convince them to drive the extra hour. Your job online is to make that drive feel unnecessary.$q$,
   $q$Dealership Marketing in Bridgewater, Nova Scotia | Shawn Ryder Digital$q$, $q$Local SEO, Google Business Profile and reviews for Bridgewater dealerships — built to keep South Shore buyers from driving to Halifax.$q$,
   $q$[{"k": "Town population", "v": "~8,800", "n": "The commercial centre of the South Shore"}, {"k": "Lunenburg County", "v": "~48,000", "n": "Plus Queens County shoppers"}, {"k": "Highway", "v": "103", "n": "Straight shot to Halifax — and back"}, {"k": "Drive to Halifax", "v": "~1 hour", "n": "Close enough to be a real alternative"}]$q$::jsonb,
   $q$[{"h": "You're competing with Halifax, not just each other", "p": "South Shore buyers will drive to the city for selection or price. Pages that show your inventory, pricing and service clearly — and why buying local is easier — keep them home."}, {"h": "Retirees, cottagers and young families", "p": "The South Shore has a large retired population alongside families and seasonal residents. Different buyers want different things — clear service information and trust matter most."}, {"h": "Summer changes the market", "p": "Seasonal residents and tourism traffic swell the area every summer. Service and used sales both feel it."}, {"h": "Service keeps customers local", "p": "A strong service department is your best argument against the Halifax drive. Make booking online easy and show your service team."}]$q$::jsonb,
   $q$[{"when": "Oct–Nov", "h": "Winter tires", "p": "Book early. Rural roads and hills make winter tires a must, and customers plan ahead."}, {"when": "Dec–Mar", "h": "Storms and salt", "p": "Coastal storms and salted roads drive AWD and rust-protection interest."}, {"when": "Apr–Jun", "h": "Spring trades and cottage season", "p": "Trades come in and seasonal residents return. Merchandise used inventory before the summer rush."}, {"when": "Jul–Sep", "h": "Summer visitors", "p": "Tourist and cottage traffic means more out-of-area service work. Keep Google hours, photos and reviews current."}]$q$::jsonb,
   $q$[{"q": "How do we stop losing buyers to Halifax dealers?", "a": "Make the local option easy to choose: real inventory with prices online, fast replies, and service that's clearly closer and more convenient."}, {"q": "Is the South Shore market big enough for paid ads?", "a": "For targeted campaigns, yes — model-specific ads to Lunenburg and Queens counties are relatively inexpensive. Start with your Google profile and reviews first."}, {"q": "Should we market to seasonal residents?", "a": "Yes, especially for service. Clear hours, easy booking and a friendly Google profile capture summer residents who need work done fast."}, {"q": "What's the first fix?", "a": "Usually speed to lead. Many South Shore leads are also talking to a Halifax store — the first real reply often wins."}]$q$::jsonb,
   coalesce((select sort_order from public.markets where slug = 'truro'), 0)),
  ($q$annapolis-valley$q$, $q$Annapolis Valley$q$, $q$Nova Scotia$q$, $q$Canada$q$, $q$Kentville, New Minas and Wolfville — an agricultural valley with a military base and a university.$q$, $q$Market page$q$, $q$Car dealership marketing in the Annapolis Valley.$q$,
   $q$The Annapolis Valley isn't one town, it's a corridor. Shoppers move along the 101 between Windsor, Wolfville, New Minas, Kentville, Berwick and Greenwood, and they compare stores the whole way. Win the corridor and you win the Valley.$q$,
   $q$Dealership Marketing in the Annapolis Valley, NS | Shawn Ryder Digital$q$, $q$Local SEO and Google profile work for Kentville, New Minas and Annapolis Valley dealerships — farm buyers, military families and Acadia students.$q$,
   $q$[{"k": "Kings County", "v": "~63,000", "n": "The heart of the Valley market"}, {"k": "Highway", "v": "101", "n": "The corridor every Valley shopper drives"}, {"k": "Military base", "v": "Greenwood", "n": "Families posted in and out every year"}, {"k": "University", "v": "Acadia", "n": "Students and staff in Wolfville"}]$q$::jsonb,
   $q$[{"h": "It's a corridor, not a town", "p": "Buyers along the 101 compare stores from Windsor to Greenwood. Your Google profile and pages should name the communities you serve, because shoppers search by their own town."}, {"h": "Military families move on a schedule", "p": "Postings to and from 14 Wing Greenwood bring buyers who need a vehicle fast and often need to sell one. Clear trade-in and financing info, and quick replies, win these deals."}, {"h": "Farm and work trucks", "p": "Agriculture drives real truck and SUV demand. Towing, payload and service availability matter more than flash."}, {"h": "Students and staff in Wolfville", "p": "Acadia brings first-car buyers and visiting parents. Simple, honest pages on reliable used options go a long way."}]$q$::jsonb,
   $q$[{"when": "Oct–Nov", "h": "Winter tires and harvest's end", "p": "Rural roads mean winter tires early. Harvest wraps up and farm buyers have time to shop."}, {"when": "Dec–Mar", "h": "Winter and slow traffic", "p": "Work your database — equity offers and service-to-sales while the lot is quiet."}, {"when": "Apr–Jul", "h": "Posting season and planting", "p": "Military postings peak in summer. Make it easy for families to buy, sell or trade on a tight timeline."}, {"when": "Aug–Sep", "h": "Back to school", "p": "Acadia students and families arrive. Reliable used vehicles and clear financing information sell."}]$q$::jsonb,
   $q$[{"q": "Should we target Greenwood military families?", "a": "Yes. Clear information on buying and selling around a posting, fast replies and flexible appointments are exactly what they need."}, {"q": "How do we rank in towns where we don't have a store?", "a": "You won't own the local pack in every Valley town, but pages that name the communities you serve, plus reviews from customers there, help you show up across the corridor."}, {"q": "Is the Valley one market or several?", "a": "For marketing, treat it as one corridor with local accents. Shoppers will drive 30 minutes along the 101 for the right vehicle and the right store."}, {"q": "What's the quickest win?", "a": "A complete Google profile and a steady review process. Many Valley stores still have thin profiles."}]$q$::jsonb,
